"use client";

import "../../styles/teum-base.css";
import "../../styles/components/context-switcher.css";
import { CaretUpDown, Check } from "@phosphor-icons/react";
import { Select as SelectPrimitive } from "@base-ui/react/select";
import type { ReactNode } from "react";
import { cn } from "../../lib/cn";

export type ContextSwitcherOption = {
  value: string;
  label: string;
  description: string;
  icon: ReactNode;
  disabled?: boolean;
};

export type ContextSwitcherProps = Omit<SelectPrimitive.Root.Props<string>, "children" | "items"> & {
  options: readonly ContextSwitcherOption[];
  "aria-label": string;
  placeholder?: string;
  className?: string;
  ref?: SelectPrimitive.Trigger.Props["ref"];
};

export function ContextSwitcher({
  options,
  value,
  defaultValue,
  onValueChange,
  open,
  defaultOpen,
  onOpenChange,
  "aria-label": ariaLabel,
  disabled,
  highlightItemOnHover = true,
  placeholder = "Choose context",
  className,
  ref,
  ...rootProps
}: ContextSwitcherProps) {
  const fallbackValue = options.find((option) => !option.disabled)?.value ?? null;
  return (
    <SelectPrimitive.Root
      items={options.map((option) => ({ label: option.label, value: option.value }))}
      value={value}
      defaultValue={defaultValue === undefined ? fallbackValue : defaultValue}
      onValueChange={onValueChange}
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
      disabled={disabled}
      highlightItemOnHover={highlightItemOnHover}
      {...rootProps}
    >
      <SelectPrimitive.Trigger ref={ref} className={cn("teum-context-switcher", className)} aria-label={ariaLabel}>
        <SelectPrimitive.Value className="teum-context-switcher__value">
          {(selectedValue) => {
            const selected = options.find((option) => option.value === selectedValue);
            if (!selectedValue || !selected) return <span className="teum-context-switcher__label" data-placeholder>{placeholder}</span>;
            return (
              <>
                <span className="teum-context-switcher__icon" aria-hidden="true">{selected.icon}</span>
                <span className="teum-context-switcher__label">{selected.label}</span>
              </>
            );
          }}
        </SelectPrimitive.Value>
        <SelectPrimitive.Icon className="teum-context-switcher__chevron"><CaretUpDown aria-hidden="true" /></SelectPrimitive.Icon>
      </SelectPrimitive.Trigger>
      <SelectPrimitive.Portal>
        <SelectPrimitive.Positioner className="teum-positioner" sideOffset={4} align="start" alignItemWithTrigger={false}>
          <SelectPrimitive.Popup className="teum-context-switcher__popup" data-layer="flyout">
            <SelectPrimitive.List className="teum-context-switcher__list" aria-label={`${ariaLabel} options`}>
              {options.map((option) => (
                <SelectPrimitive.Item className="teum-context-switcher__item" key={option.value} value={option.value} disabled={option.disabled}>
                  <span className="teum-context-switcher__item-icon" aria-hidden="true">{option.icon}</span>
                  <span className="teum-context-switcher__copy">
                    <SelectPrimitive.ItemText className="teum-context-switcher__item-label">{option.label}</SelectPrimitive.ItemText>
                    <span className="teum-context-switcher__description">{option.description}</span>
                  </span>
                  <SelectPrimitive.ItemIndicator className="teum-context-switcher__indicator"><Check weight="bold" aria-hidden="true" /></SelectPrimitive.ItemIndicator>
                </SelectPrimitive.Item>
              ))}
            </SelectPrimitive.List>
          </SelectPrimitive.Popup>
        </SelectPrimitive.Positioner>
      </SelectPrimitive.Portal>
    </SelectPrimitive.Root>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-context-switcher {
  display: inline-flex;
  width: min(252px, 100%);
  height: 38px;
  align-items: center;
  gap: 8px;
  padding: 0 9px;
  border: 1px solid var(--teum-control-border);
  border-radius: 9px;
  background: color-mix(in oklab, var(--teum-bg-subtle) 42%, var(--teum-bg-control));
  box-shadow: var(--teum-shadow-control);
  color: var(--teum-fg-default);
  font: inherit;
  cursor: pointer;
  transition: background-color var(--teum-hover-duration), border-color var(--teum-hover-duration), box-shadow var(--teum-hover-duration), transform var(--teum-press-duration) var(--teum-ease-out);
}

.teum-context-switcher__value { display: flex; min-width: 0; flex: 1; align-items: center; gap: 8px; }

.teum-context-switcher__icon,
.teum-context-switcher__item-icon { display: grid; width: 17px; height: 17px; flex: 0 0 auto; place-items: center; color: var(--teum-fg-muted); }

.teum-context-switcher__icon svg,
.teum-context-switcher__item-icon svg { width: 16px; height: 16px; }

.teum-context-switcher__label { overflow: hidden; font-size: var(--teum-type-ui); font-weight: 540; text-overflow: ellipsis; white-space: nowrap; }

.teum-context-switcher__chevron { display: grid; width: 16px; height: 16px; flex: 0 0 auto; place-items: center; color: var(--teum-fg-subtle); }

.teum-context-switcher__chevron svg { width: 14px; height: 14px; }

.teum-context-switcher:not([data-disabled]):hover,
.teum-context-switcher[data-popup-open] { border-color: var(--teum-control-border-hover); background: var(--teum-bg-control); box-shadow: var(--teum-shadow-float); }

.teum-context-switcher:active:not([data-disabled]) { transform: scale(.985); }

.teum-context-switcher:focus-visible { outline: 0; border-color: var(--teum-control-border-hover); background: var(--teum-bg-control); box-shadow: var(--teum-shadow-control); }

.teum-context-switcher[data-disabled] { color: var(--teum-fg-disabled); cursor: not-allowed; box-shadow: none; }

.teum-context-switcher__popup {
  min-width: var(--anchor-width);
  max-width: min(320px, calc(100vw - 20px));
  max-height: min(360px, var(--available-height));
  overflow: hidden;
  border: 1px solid var(--teum-border);
  border-radius: var(--teum-radius-md);
  background: var(--teum-bg-flyout);
  box-shadow: var(--teum-shadow-flyout);
  color: var(--teum-fg-default);
  transform-origin: var(--transform-origin);
  transition: opacity var(--teum-enter-duration) var(--teum-ease-out), transform var(--teum-enter-duration) var(--teum-ease-out);
}

.teum-context-switcher__popup[data-starting-style],
.teum-context-switcher__popup[data-ending-style] { opacity: 0; transform: translateY(-2px) scale(.99); }

.teum-context-switcher__popup[data-ending-style] { transition-duration: var(--teum-exit-duration); }

.teum-context-switcher__list { display: grid; gap: 2px; padding: 4px; overflow-y: auto; }

.teum-context-switcher__item {
  display: grid;
  min-height: 44px;
  grid-template-columns: 17px minmax(0, 1fr) 14px;
  align-items: center;
  gap: 9px;
  padding: 6px 8px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  outline: 0;
  color: var(--teum-fg-muted);
  font: inherit;
  text-align: left;
  cursor: default;
  user-select: none;
  transition: background-color var(--teum-hover-duration), box-shadow var(--teum-hover-duration);
}

.teum-context-switcher__copy { display: grid; min-width: 0; gap: 3px; }

.teum-context-switcher__item-label { overflow: hidden; font-size: var(--teum-type-ui); font-weight: 550; line-height: 1.1; text-overflow: ellipsis; white-space: nowrap; }

.teum-context-switcher__description { overflow: hidden; color: var(--teum-fg-subtle); font-size: var(--teum-type-label); line-height: 1.2; text-overflow: ellipsis; white-space: nowrap; }

.teum-context-switcher__indicator { display: grid; width: 14px; height: 14px; place-items: center; color: var(--teum-fg-default); }

.teum-context-switcher__indicator svg { width: 12px; height: 12px; }

.teum-context-switcher__item:hover,
.teum-context-switcher__item[data-highlighted] { background: var(--teum-hover); color: var(--teum-fg-default); }

.teum-context-switcher__item[data-disabled] { color: var(--teum-fg-disabled); cursor: not-allowed; }

.teum-context-switcher__item[data-disabled] .teum-context-switcher__description,
.teum-context-switcher__item[data-disabled] .teum-context-switcher__item-icon { color: var(--teum-fg-disabled); }

.teum-positioner { z-index: var(--teum-layer-flyout); }

.teum-context-switcher__popup {
  scrollbar-color: var(--teum-scrollbar-thumb) transparent;
  scrollbar-width: thin;
}

.teum-context-switcher__popup::-webkit-scrollbar { width: 10px; height: 10px; }

.teum-context-switcher__popup::-webkit-scrollbar-track { background: transparent; }

.teum-context-switcher__popup::-webkit-scrollbar-thumb {
  border: 3px solid transparent;
  border-radius: 999px;
  background: var(--teum-scrollbar-thumb);
  background-clip: padding-box;
}

.teum-context-switcher__popup::-webkit-scrollbar-thumb:hover { background: var(--teum-scrollbar-thumb-hover); background-clip: padding-box; }

@media (forced-colors: active) {
.teum-context-switcher__popup { scrollbar-color: auto; }
}

@media (prefers-reduced-motion: reduce) {
.teum-context-switcher__popup {
    transition-property: opacity;
    transition-duration: var(--teum-exit-duration);
  }

.teum-context-switcher__popup[data-starting-style],
.teum-context-switcher__popup[data-ending-style] { transform: none; }

.teum-context-switcher:active { transform: none; }

.teum-context-switcher__chevron svg { transition-duration: 0.01ms; }
}
}
